#!/usr/bin/env python3
"""Generate a crawlable, source-pinned native catalog; no network or client JS needed."""
from collections import defaultdict
from html import escape
from pathlib import Path
import argparse,json
R=Path(__file__).resolve().parent.parent
BASE='https://jangtrinh.github.io/design-os-apple/'
BADGES={'source-only':'Source inspected · no standalone preview','native-capture':'Native capture · source matched','historical-native-capture':'Historical native capture · current review pending'}
def e(v):return escape(str(v),quote=True)
def link(url,label,cls=''):return f'<a href="{e(url)}"'+(f' class="{e(cls)}"' if cls else '')+f'>{e(label)}</a>'
def fact(label,value):return f'<dt>{e(label)}</dt><dd>{value}</dd>'
def render(data,manifest):
 assets={a['file']:a for a in manifest['assets']};entries=[i for g in data['groups'] for i in g['items']];counts=data['counts'];head=data['sourceCommit'];canonical=BASE+'components.html'
 schema={'@context':'https://schema.org','@graph':[{'@type':'CollectionPage','@id':canonical+'#page','url':canonical,'name':'Apple Design OS native SwiftUI component catalog','description':'Source-backed components and original native light/dark fixture previews.','inLanguage':'en','dateModified':data['generatedDate'],'isPartOf':{'@id':BASE+'#website'},'mainEntity':{'@id':canonical+'#inventory'}},{'@type':'ItemList','@id':canonical+'#inventory','name':'Apple Design OS source inventory','numberOfItems':len(entries),'itemListElement':[{'@type':'ListItem','position':n+1,'item':{'@type':'CreativeWork','name':i['name'],'url':canonical+'#'+i['id'],'description':i['summary']}} for n,i in enumerate(entries)]}]}
 out=['<!doctype html>','<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Native SwiftUI component catalog — Apple Design OS</title>', '<meta name="description" content="Browse every Apple Design OS primitive, semantic component, composite, shell and screen type, with original native iPhone light/dark previews, API configuration and source evidence.">', '<meta name="robots" content="index, follow, max-image-preview:large">',f'<link rel="canonical" href="{canonical}"><link rel="alternate" type="text/plain" href="llms.txt" title="AI-readable documentation"><meta property="og:type" content="website"><meta property="og:title" content="Native SwiftUI component catalog — Apple Design OS"><meta property="og:description" content="Every source-backed layer, with original native previews and explicit coverage limits."><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}assets/marketing/kit-overview.png"><meta property="og:image:width" content="2000"><meta property="og:image:height" content="1000"><meta property="og:image:alt" content="Apple Design OS native iPhone, iPad and Mac compositions from the historical adcf88a capture set"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="Native SwiftUI component catalog — Apple Design OS"><meta name="twitter:description" content="Every source-backed layer, with original native previews and explicit coverage limits."><meta name="twitter:image" content="{BASE}assets/marketing/kit-overview.png"><meta name="twitter:image:alt" content="Original Apple Design OS native compositions; historical adcf88a capture set">','<link rel="stylesheet" href="assets/site.css"><link rel="stylesheet" href="assets/components.css"><script defer src="assets/components.js"></script>', '<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False).replace('</',r'<\/')+'</script></head>', '<body class="marketing catalog"><a class="ds-skip-link" href="#main">Skip to catalog</a><header class="marketing-nav wrap"><a class="brand" href="./">design<span>:os</span><span class="brand-platform">/ apple</span></a><nav aria-label="Primary"><a href="./">Overview</a><a href="#catalog-content" aria-current="page">Components</a><a href="kit-architecture.html">Architecture</a><a href="https://github.com/jangtrinh/design-os-apple">GitHub</a></nav></header>', '<main id="main" class="wrap"><section class="catalog-intro" aria-labelledby="catalog-title"><p class="eyebrow">Apple Design OS · native SwiftUI</p><h1 id="catalog-title">Every component.</h1>',f'<p>{len(entries)} source entries · {counts["designTokenLeaves"]} token values · {len(manifest["assets"])} published native images · source {head[:7]}</p>','<p>Primitives, semantic components, composites, shells and screen types on one page. Every visual entry shows a light/dark pair. Source helpers without a standalone image are labeled separately.</p>','<details class="catalog-disclosures"><summary>Source, captures &amp; review status</summary>', '<p>The layered kit is now on main. Source links and the native previews below are pinned to '+link('https://github.com/jangtrinh/design-os-apple/tree/'+head,head[:7])+'. Merged main 56f10a1 has the same source tree. No tagged release is claimed.</p>', '<p>'+link(data['nativeEvidence']['runUrl'],'Native CI run 38157622095')+' passed all 24 checks. Its reviewed evidence covers 360 isolated component captures, 108 screen-family captures and 42 dedicated text-field states across iPhone, iPad and Mac. The isolated set includes RTL and accessibility-size cases; this is not a claim of complete accessibility acceptance.</p>', '<p>This page publishes 142 original native iPhone images: 106 isolated defaults and 36 screen-family fixtures. Other state/platform evidence is linked separately when its source identity is verified. An artifact link is not a hosted preview. Source identity, exact hashes and display crops are recorded in the '+link('assets/components/manifest.json','image manifest')+'.</p>', '<p>These captures are original fixture UI, with synthetic example content. Native execution, image review and complete product behavior are separate. No guarantee is made about every visual state, physical-device behavior, live services or complete accessibility acceptance. '+link('marketing/component-catalog.json','Read the complete source inventory')+'.</p></details></section>', '<nav class="catalog-toc" aria-label="Catalog sections">']
 out.extend(link('#'+g['id'],g['title']) for g in data['groups']);out.extend([link('#token-values','Token values'),link('#native-evidence','State & platform evidence'),'</nav>','<div class="catalog-tools" hidden><div class="catalog-search-row"><div class="catalog-search-field"><label for="catalog-search">Find a component, variant, or use</label><input id="catalog-search" type="search" placeholder="Try avatar, form, or navigation" autocomplete="off" aria-controls="catalog-content"></div><button class="pill secondary catalog-reset" id="catalog-reset" type="button">Reset filters</button></div><div class="catalog-filters" role="group" aria-label="Filter by layer"><button type="button" data-filter="all" aria-pressed="true">All layers</button>'])
 out.extend(f'<button type="button" data-filter="{e(g["id"])}" aria-pressed="false">{e(g["title"])}</button>' for g in data['groups']);out.extend([f'</div><p id="catalog-status" role="status" aria-live="polite" aria-atomic="true">{len(entries)} of {len(entries)} entries shown.</p></div>','<noscript><p>All entries and images are present without JavaScript. Use your browser’s Find command to search.</p></noscript><p id="catalog-empty" class="catalog-empty" hidden>No matching components. Try another term or reset the filters.</p><div id="catalog-content">'])
 for g in data['groups']:
  out.append(f'<section class="catalog-group" id="{e(g["id"])}" data-group="{e(g["id"])}" aria-labelledby="{e(g["id"])}-title"><div class="catalog-group-header"><h2 id="{e(g["id"])}-title">{e(g["title"])}</h2><span class="catalog-group-count">{len(g["items"])} entries</span></div><p class="catalog-group-description">{e(g["description"])}</p><div class="component-grid">')
  for i in g['items']:
   out.append(f'<article class="component-entry" id="{e(i["id"])}" data-layer="{e(g["id"])}"><span class="component-layer">{e(i["layer"])} · {e(i["visibility"])}</span>')
   p=i.get('preview')
   if p:
    out.append('<div class="component-preview"><div class="component-preview-pair">')
    for key,theme in [('src','light'),('darkSrc','dark')]:
     src=p.get(key)
     if not src:continue
     a=assets[Path(src).name];alt=p['alt']+(' · '+theme if p.get('darkSrc') else '')
     out.append(f'<figure><a href="{e(src)}"><img src="{e(src)}" alt="{e(alt)}" width="{a["width"]}" height="{a["height"]}" loading="lazy" decoding="async"></a><figcaption>{theme.capitalize()}</figcaption></figure>')
    out.append('</div><p class="component-preview-caption">'+e(p['caption'])+'</p></div>')
   else:out.append('<div class="component-pending" role="note"><span>No standalone visual specimen</span></div>')
   out.extend(['<h3>'+link('#'+i['id'],i['name'])+'</h3>','<p class="component-evidence"><strong>'+e(BADGES[i['review']['status']])+'</strong></p>','<p class="component-summary">'+e(i['summary'])+'</p>','<details class="component-metadata"><summary>API, variants &amp; evidence</summary><dl class="component-facts">',fact('API','<code>'+e(i['symbol'])+'</code>'),fact('Variants / configuration','<br>'.join(e(v) for v in i['variants'])),fact('Use it for',e(i['usage']))])
   if i.get('fixtureStates'):out.append(fact('Fixture states',', '.join(e(v) for v in i['fixtureStates'])))
   if i.get('dependencies'):out.append(fact('Composes',', '.join(link('#'+v,v) for v in i['dependencies'])))
   out.append('</dl>');conf=i.get('configuration',{})
   if conf.get('initializers') or conf.get('parameters') or conf.get('enumCases'):
    out.append('<div class="component-signatures"><h4>Public configuration</h4>');out.extend('<p><code>'+e(v)+'</code></p>' for v in conf.get('initializers',[]));out.extend('<p><code>'+e(v['declaration'])+'</code></p>' for v in conf.get('parameters',[]))
    cases=[v['name']+': '+', '.join(v['cases']) if isinstance(v,dict) else v for v in conf.get('enumCases',[])];out.append('<p>'+e('; '.join(cases))+'</p></div>')
   if i.get('nativeAPIs'):
    out.append('<div class="native-api-list"><h4>Apple-owned APIs</h4><ul>');out.extend('<li>'+link(a['evidenceUrl'],a['name'])+': '+e(a['reviewDetail'])+'</li>' for a in i['nativeAPIs']);out.append('</ul></div>')
   out.append('<p class="component-review-detail">'+e(i['review']['detail'])+'</p>'+link(i['source']['url'],'Inspect Swift source','component-source')+'</details></article>')
  out.append('</div></section>')
 out.append('</div><section class="catalog-token-section" id="token-values" aria-labelledby="token-values-title"><h2 id="token-values-title">Token values</h2><p>Design token leaves are separate from Swift semantic role families. These are values, not extra components.</p>');types=defaultdict(list)
 for t in data['tokens']:types[t['type']].append(t)
 for kind,tokens in types.items():
  out.append(f'<div class="token-type"><h3>{e(kind)}</h3><ul class="token-grid">')
  for t in tokens:
   v=t['value'];text='; '.join(f'{k}: {a}' for k,a in v.items()) if isinstance(v,dict) else str(v);swatch=f'<span class="token-swatch" style="background:{e(v)}" aria-hidden="true"></span>' if kind=='color' and isinstance(v,str) else ''
   out.append(f'<li class="catalog-token" id="{e(t["id"])}">{swatch}<div><strong>{e(t["path"])}</strong><span>{e(text)}</span></div></li>')
  out.append('</ul></div>')
 out.append('</section><section id="native-evidence" class="catalog-token-section" aria-labelledby="native-evidence-title"><h2 id="native-evidence-title">Every captured state and platform</h2><p>The complete inventory contains 510 original native captures: 170 each for iPhone, iPad and Mac. This page displays 142 iPhone previews above. The records below link the original CI artifacts for all captures, including other platforms and states. Artifact downloads may require GitHub sign-in and are subject to retention; they are not directly hosted images.</p><p>Capture metadata has been authenticated again against native test attachments. Earlier scoped review is recorded; the full 510-image pixel review has not been repeated during this recovery. '+link('marketing/native-capture-index.json','Download the complete machine-readable image inventory')+'.</p>')
 evidence=json.loads((R/'docs/marketing/native-capture-index.json').read_text())
 for platform,label in [('iphone','iPhone'),('ipad','iPad'),('macos','Mac')]:
  records=[r for r in evidence['records'] if r['platform']==platform]
  out.append('<details class="native-evidence-group"><summary>'+label+' · '+str(len(records))+' source-bound captures</summary><ul class="native-evidence-list">')
  for r in records:
   artifact=evidence['artifacts'][str(r['artifact_id'])];caption=r['component_id']+' · '+r['state']+' · '+r['appearance']
   out.append('<li data-capture-id="'+e(r['id'])+'">'+link(artifact['url'],caption)+' <span>'+e(r['kind'].replace('_',' '))+' · '+e(r['capture']['width'])+'×'+e(r['capture']['height'])+'</span> '+link(r['job_url'],'Native test job')+'</li>')
  out.append('</ul></details>')
 out.append('</section>')
 out.append('<footer class="catalog-footer">'+link('./','Overview')+link('kit-architecture.html','Architecture')+link('marketing/component-catalog.json','Source inventory')+link('assets/components/manifest.json','Native image provenance')+'</footer></main></body></html>');return '\n'.join(out)+'\n'
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--check',action='store_true');args=p.parse_args();result=render(json.loads((R/'docs/marketing/component-catalog.json').read_text()),json.loads((R/'docs/assets/components/manifest.json').read_text()));dest=R/'docs/components.html'
 if args.check:
  if dest.read_text()!=result:raise SystemExit('Catalog HTML is stale; run scripts/generate-component-catalog.py')
  print('Catalog HTML matches its source-pinned inventory.')
 else:dest.write_text(result)
if __name__=='__main__':main()
